-- Rebuild Medina Book 4 lesson 17 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 68-70. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '17';
  if existing_count <> 5 then
    raise exception 'Expected 5 Book 4 lesson 17 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الْمَمْنُوعُ مِنَ الصَّرْفِ (имя, не принимающее танвин)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ هُوَ الِاسْمُ الْمُعْرَبُ الَّذِي لَا يُنَوَّنُ، وَهُوَ قِسْمَانِ: مَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ، وَمَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّتَيْنِ.</span><p class="rule-study-text">Это изменяемое имя, которое не принимает танвин. Шарх делит такие имена на две группы: запрещённые к обычному склонению по одной причине и по двум причинам.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Определение</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْمُعْرَبُ الَّذِي لَا يُنَوَّنُ</span><span class="rule-term-ru">изменяемое имя, которое не принимает танвин</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два раздела</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقِسْمُ</span><span class="rule-table-ru">раздел</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ</span><span class="rule-table-ru">не принимает обычное склонение по одной причине</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْقِسْمُ الْأَوَّلُ</span><span class="rule-table-ru">первая группа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّتَيْنِ</span><span class="rule-table-ru">не принимает обычное склонение по двум причинам</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْقِسْمُ الثَّانِي</span><span class="rule-table-ru">вторая группа</span></td></tr></tbody></table></div></div></div>', 'Это изменяемое имя, которое не принимает танвин. Шарх делит такие имена на две группы: запрещённые к обычному склонению по одной причине и по двум причинам.', 'الْمَمْنُوعُ مِنَ الصَّرْفِ هُوَ الِاسْمُ الْمُعْرَبُ الَّذِي لَا يُنَوَّنُ، وَهُوَ قِسْمَانِ: مَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ، وَمَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّتَيْنِ.'),
    (2, 'الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ (имена, не принимающие обычное склонение по одной причине)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">يُمْنَعُ الِاسْمُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ فِي ثَلَاثَةِ أَنْوَاعٍ: الْمَخْتُومُ بِأَلِفِ التَّأْنِيثِ الْمَقْصُورَةِ أَوِ الْمَمْدُودَةِ، بِشَرْطِ أَنْ تَكُونَ الْأَلِفُ زَائِدَةً لَا أَصْلِيَّةً؛ وَصِيغَةُ مُنْتَهَى الْجُمُوعِ وَأَشْبَاهُهَا؛ وَالْمُفْرَدُ الَّذِي عَلَى وَزْنِ صِيغَةِ مُنْتَهَى الْجُمُوعِ.</span><p class="rule-study-text">По одной причине обычного склонения не принимают три вида: слова с добавочным алифом женского рода, формы предельного множественного и единственные слова, построенные по весу такой формы множественного.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три вида и все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الشَّرْطُ أَوِ الْوَزْنُ</span><span class="rule-table-ru">условие или модель</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَخْتُومُ بِأَلِفِ التَّأْنِيثِ</span><span class="rule-table-ru">слово с алифом женского рода в конце</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَقْصُورَةُ أَوِ الْمَمْدُودَةُ، وَالْأَلِفُ زَائِدَةٌ لَا أَصْلِيَّةٌ</span><span class="rule-table-ru">алиф укороченный или удлинённый и обязательно добавочный, а не коренной</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَرْضَى، جَرْحَى، يَتَامَى؛ صَحْرَاءَ، أَغْنِيَاءَ، حَمْرَاءَ.</span><span class="rule-table-ru">больные, раненые, сироты; пустыня, богатые, красная</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِيغَةُ مُنْتَهَى الْجُمُوعِ وَأَشْبَاهُهَا</span><span class="rule-table-ru">форма предельного множественного и сходные с ней модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَفَاعِلُ وَمَفَاعِيلُ وَأَشْبَاهُهُمَا</span><span class="rule-table-ru">модели «мафа‘иль», «мафа‘ииль» и подобные им</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَسَاجِدَ، فَنَادِقَ؛ مَصَابِيحَ، ثَعَابِينَ.</span><span class="rule-table-ru">мечети, гостиницы; светильники, змеи</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ عَلَى وَزْنِ مُنْتَهَى الْجُمُوعِ</span><span class="rule-table-ru">единственное слово по модели предельного множественного</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَفْظٌ مُفْرَدٌ عَلَى هَذَا الْوَزْنِ</span><span class="rule-table-ru">слово имеет единственное значение, но такую же модель</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">بَطَاطِسَ، طَمَاطِمَ، طَبَاشِيرَ، سَرَاوِيلَ.</span><span class="rule-table-ru">картофель, помидоры, мелки, брюки</span></td></tr></tbody></table></div></div></div>', 'По одной причине обычного склонения не принимают три вида: слова с добавочным алифом женского рода, формы предельного множественного и единственные слова, построенные по весу такой формы множественного.', 'يُمْنَعُ الِاسْمُ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ فِي ثَلَاثَةِ أَنْوَاعٍ: الْمَخْتُومُ بِأَلِفِ التَّأْنِيثِ الْمَقْصُورَةِ أَوِ الْمَمْدُودَةِ، بِشَرْطِ أَنْ تَكُونَ الْأَلِفُ زَائِدَةً لَا أَصْلِيَّةً؛ وَصِيغَةُ مُنْتَهَى الْجُمُوعِ وَأَشْبَاهُهَا؛ وَالْمُفْرَدُ الَّذِي عَلَى وَزْنِ صِيغَةِ مُنْتَهَى الْجُمُوعِ.'),
    (3, 'الْعَلَمُ الْمَمْنُوعُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ (собственные имена, не принимающие обычное склонение по двум причинам)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">تُمْنَعُ الْأَعْلَامُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ فِي سِتَّةِ أَنْوَاعٍ: الْعَلَمُ الْمُؤَنَّثُ، وَالْعَلَمُ الْأَعْجَمِيُّ، وَالْعَلَمُ الَّذِي عَلَى وَزْنِ الْفِعْلِ، وَالْعَلَمُ الْمَعْدُولُ، وَالْعَلَمُ الْمَخْتُومُ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ، وَالْعَلَمُ الْمُرَكَّبُ تَرْكِيبًا مَزْجِيًّا. وَيَجُوزُ فِي الْعَلَمِ الْمُؤَنَّثِ الثُّلَاثِيِّ السَّاكِنِ الْوَسَطِ الصَّرْفُ وَالْمَنْعُ، وَالْمَنْعُ أَوْلَى. وَيُصْرَفُ الْعَلَمُ الْأَعْجَمِيُّ الثُّلَاثِيُّ السَّاكِنُ الْوَسَطِ إِذَا كَانَ مُذَكَّرًا، وَيُمْنَعُ إِذَا كَانَ مُؤَنَّثًا.</span><p class="rule-study-text">Шарх перечисляет шесть видов собственных имён и отдельно устанавливает исключения для трёхбуквенных женских и иностранных имён с неподвижной средней буквой.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Шесть видов собственных имён</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ الْمُؤَنَّثُ</span><span class="rule-table-ru">женское собственное имя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">فَاطِمَةَ، حَمْزَةَ، مَرْيَمَ.</span><span class="rule-table-ru">Фатима, Хамза, Марьям</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ الْأَعْجَمِيُّ</span><span class="rule-table-ru">иностранное собственное имя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">إِبْرَاهِيمَ، إِسْحَاقَ، لَنْدَنَ، بَاكِسْتَانَ.</span><span class="rule-table-ru">Ибрахим, Исхак, Лондон, Пакистан</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ عَلَى وَزْنِ الْفِعْلِ</span><span class="rule-table-ru">собственное имя по модели глагола</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَحْمَدَ، يَزِيدَ، يَنْبُعَ.</span><span class="rule-table-ru">Ахмад, Язид, Янбу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ الْمَعْدُولُ</span><span class="rule-table-ru">изменённое собственное имя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عُمَرَ مِنْ عَامِرٍ، وَزُفَرَ مِنْ زَافِرٍ، وَهُبَلَ مِنْ هَابِلٍ.</span><span class="rule-table-ru">Умар от Амир, Зуфар от Зафир, Хубаль от Хабиль</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمَخْتُومُ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ</span><span class="rule-table-ru">собственное имя с добавочными алифом и нуном в конце</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عُثْمَانَ، رَمَضَانَ، مَرْوَانَ.</span><span class="rule-table-ru">Усман, Рамадан, Марван</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُرَكَّبُ تَرْكِيبًا مَزْجِيًّا</span><span class="rule-table-ru">слитное составное собственное имя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَضْرَمَوْتَ، بَعْلَبَكَّ، مَعْدِيكَرِبَ.</span><span class="rule-table-ru">Хадрамаут, Баальбек, Мадикариб</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Особые случаи трёхбуквенных имён</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلَمٌ مُؤَنَّثٌ ثُلَاثِيٌّ سَاكِنُ الْوَسَطِ</span><span class="rule-table-ru">трёхбуквенное женское имя с неподвижной средней буквой</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ صَرْفُهُ وَمَنْعُهُ، وَمَنْعُهُ أَوْلَى</span><span class="rule-table-ru">допустимы оба варианта, но отказ от обычного склонения предпочтительнее</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">هِنْدٍ، رِيمٍ، دَعْدٍ.</span><span class="rule-table-ru">Хинд, Рим, Даад</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلَمٌ أَعْجَمِيٌّ ثُلَاثِيٌّ سَاكِنُ الْوَسَطِ مُذَكَّرٌ</span><span class="rule-table-ru">трёхбуквенное иностранное мужское имя с неподвижной средней буквой</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُصْرَفُ</span><span class="rule-table-ru">склоняется обычно и принимает танвин</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نُوحٍ، لُوطٍ، شَاهٍ.</span><span class="rule-table-ru">Нух, Лут, Шах</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلَمٌ أَعْجَمِيٌّ مُؤَنَّثٌ</span><span class="rule-table-ru">иностранное женское собственное имя</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُمْنَعُ مِنَ الصَّرْفِ</span><span class="rule-table-ru">не принимает обычного склонения</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مُوشَ، نِيسَ، بَلْخَ.</span><span class="rule-table-ru">Муш, Ницца, Балх</span></td></tr></tbody></table></div></div></div>', 'Шарх перечисляет шесть видов собственных имён и отдельно устанавливает исключения для трёхбуквенных женских и иностранных имён с неподвижной средней буквой.', 'تُمْنَعُ الْأَعْلَامُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ فِي سِتَّةِ أَنْوَاعٍ: الْعَلَمُ الْمُؤَنَّثُ، وَالْعَلَمُ الْأَعْجَمِيُّ، وَالْعَلَمُ الَّذِي عَلَى وَزْنِ الْفِعْلِ، وَالْعَلَمُ الْمَعْدُولُ، وَالْعَلَمُ الْمَخْتُومُ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ، وَالْعَلَمُ الْمُرَكَّبُ تَرْكِيبًا مَزْجِيًّا. وَيَجُوزُ فِي الْعَلَمِ الْمُؤَنَّثِ الثُّلَاثِيِّ السَّاكِنِ الْوَسَطِ الصَّرْفُ وَالْمَنْعُ، وَالْمَنْعُ أَوْلَى. وَيُصْرَفُ الْعَلَمُ الْأَعْجَمِيُّ الثُّلَاثِيُّ السَّاكِنُ الْوَسَطِ إِذَا كَانَ مُذَكَّرًا، وَيُمْنَعُ إِذَا كَانَ مُؤَنَّثًا.'),
    (4, 'الصِّفَةُ الْمَمْنُوعَةُ مِنَ الصَّرْفِ (прилагательные, не принимающие обычное склонение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-predicate" dir="rtl" lang="ar">تُمْنَعُ الصِّفَةُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ فِي ثَلَاثَةِ أَنْوَاعٍ: مَا كَانَ عَلَى وَزْنِ أَفْعَلَ بِشَرْطِ أَلَّا يَكُونَ مُؤَنَّثُهُ بِالتَّاءِ؛ وَمَا خُتِمَ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ عَلَى وَزْنِ فَعْلَانَ؛ وَالصِّفَةُ الْمَعْدُولَةُ، وَهِيَ الْعَدَدُ عَلَى وَزْنَيْ مَفْعَلٍ وَفُعَالٍ إِلَى عَشَرَةٍ، وَلَفْظُ أُخَرَ.</span><p class="rule-study-text">Не принимают обычного склонения прилагательные модели «аф‘аль» при указанном условии, прилагательные модели «фа‘ляан» с добавочными алифом и нуном и два вида изменённых прилагательных.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Виды, условия и примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ أَوِ الْحُكْمُ</span><span class="rule-table-ru">условие или правило</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الصِّفَةُ عَلَى وَزْنِ أَفْعَلَ</span><span class="rule-table-ru">прилагательное по модели «аф‘аль»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَلَّا يَكُونَ مُؤَنَّثُهُ بِالتَّاءِ</span><span class="rule-table-ru">женская форма не должна образовываться с помощью та</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَكْبَرَ، أَحْمَرَ، أَحْسَنَ.</span><span class="rule-table-ru">больше, красный, лучше</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُؤَنَّثُهُ بِالتَّاءِ</span><span class="rule-table-ru">женская форма образуется с помощью та</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَصْرُوفٌ</span><span class="rule-table-ru">обычно склоняется и принимает танвин</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَرْمَلٌ؛ مُؤَنَّثُهُ أَرْمَلَةٌ.</span><span class="rule-table-ru">вдовец; женская форма — вдова</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَخْتُومُ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ</span><span class="rule-table-ru">прилагательное с добавочными алифом и нуном в конце</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عَلَى وَزْنِ فَعْلَانَ</span><span class="rule-table-ru">модель «фа‘ляан»</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">غَضْبَانَ، فَرْحَانَ، عَطْشَانَ.</span><span class="rule-table-ru">сердитый, радостный, испытывающий жажду</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْعَدَدُ الْمَعْدُولُ</span><span class="rule-table-ru">изменённое числительное-прилагательное</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عَلَى وَزْنَيْ مَفْعَلٍ وَفُعَالٍ إِلَى عَشَرَةٍ</span><span class="rule-table-ru">по двум моделям вплоть до числа десять</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَثْنَى وَثُنَاءَ، وَمَثْلَثَ وَثُلَاثَ.</span><span class="rule-table-ru">по два; по три</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَفْظُ أُخَرَ</span><span class="rule-table-ru">слово «другие»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِفَةٌ مَعْدُولَةٌ</span><span class="rule-table-ru">изменённое прилагательное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أُخَرَ</span><span class="rule-table-ru">другие, женский род множественного числа</span></td></tr></tbody></table></div></div></div>', 'Не принимают обычного склонения прилагательные модели «аф‘аль» при указанном условии, прилагательные модели «фа‘ляан» с добавочными алифом и нуном и два вида изменённых прилагательных.', 'تُمْنَعُ الصِّفَةُ مِنَ الصَّرْفِ لِعِلَّتَيْنِ فِي ثَلَاثَةِ أَنْوَاعٍ: مَا كَانَ عَلَى وَزْنِ أَفْعَلَ بِشَرْطِ أَلَّا يَكُونَ مُؤَنَّثُهُ بِالتَّاءِ؛ وَمَا خُتِمَ بِأَلِفٍ وَنُونٍ زَائِدَتَيْنِ عَلَى وَزْنِ فَعْلَانَ؛ وَالصِّفَةُ الْمَعْدُولَةُ، وَهِيَ الْعَدَدُ عَلَى وَزْنَيْ مَفْعَلٍ وَفُعَالٍ إِلَى عَشَرَةٍ، وَلَفْظُ أُخَرَ.'),
    (5, 'أَحْكَامُ الْمَمْنُوعِ مِنَ الصَّرْفِ (правила грамматического изменения имени без танвина)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-jarr" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ لَا يُنَوَّنُ، وَيُجَرُّ بِالْفَتْحَةِ نِيَابَةً عَنِ الْكَسْرَةِ، إِلَّا إِذَا اقْتَرَنَ بِأَلْ أَوْ أُضِيفَ فَيُجَرُّ بِالْكَسْرَةِ. وَالِاسْمُ الْمَنْقُوصُ الَّذِي عَلَى صِيغَةِ مُنْتَهَى الْجُمُوعِ، كَمَعَانٍ وَجَوَارٍ، يُعَامَلُ مُعَامَلَةَ الْمُفْرَدِ الْمَنْقُوصِ.</span><p class="rule-study-text">Такое имя не принимает танвин и в родительном состоянии получает фатху вместо касры. При определённом артикле или идафе возвращается касра. Отдельно шарх разбирает неполные имена формы предельного множественного.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Основные правила</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا يُنَوَّنُ</span><span class="rule-table-ru">не принимает танвин</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَذْفُ التَّنْوِينِ</span><span class="rule-table-ru">танвин отсутствует</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">يُجَرُّ بِالْفَتْحَةِ نِيَابَةً عَنِ الْكَسْرَةِ</span><span class="rule-table-ru">в родительном состоянии получает фатху вместо касры</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا كَانَ مُجَرَّدًا مِنْ أَلْ وَالْإِضَافَةِ</span><span class="rule-table-ru">когда нет определённого артикля и идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">إِذَا اقْتَرَنَ بِأَلْ أَوْ أُضِيفَ يُجَرُّ بِالْكَسْرَةِ</span><span class="rule-table-ru">с определённым артиклем или в идафе получает касру</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">رُجُوعُ الْكَسْرَةِ</span><span class="rule-table-ru">возвращается обычный показатель родительного состояния</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три примера родительного состояния</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْعَلَامَةُ</span><span class="rule-table-ru">окончание</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُجَرَّدٌ مِنْ أَلْ وَالْإِضَافَةِ</span><span class="rule-table-ru">без артикля и без идафы</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ.</span><span class="rule-table-ru">Я совершал молитву во многих мечетях.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْفَتْحَةُ</span><span class="rule-table-ru">фатха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُقْتَرِنٌ بِأَلْ</span><span class="rule-table-ru">с определённым артиклем</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">صَلَّيْتُ فِي الْمَسَاجِدِ.</span><span class="rule-table-ru">Я совершал молитву в мечетях.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْكَسْرَةُ</span><span class="rule-table-ru">касра</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَافٌ</span><span class="rule-table-ru">первый член идафы</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">صَلَّيْتُ فِي مَسَاجِدِ الْمَدِينَةِ.</span><span class="rule-table-ru">Я совершал молитву в мечетях города.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْكَسْرَةُ</span><span class="rule-table-ru">касра</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неполное имя на форме предельного множественного</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ الْإِعْرَابِيَّةُ</span><span class="rule-table-ru">падежное состояние</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">полный разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الرَّفْعُ</span><span class="rule-table-ru">именительное состояние</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">لِهَذِهِ الْكَلِمَةِ مَعَانٍ كَثِيرَةٌ.</span><span class="rule-table-ru">У этого слова много значений.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ بِضَمَّةٍ مُقَدَّرَةٍ، وَالتَّنْوِينُ لِلْعِوَضِ.</span><span class="rule-table-ru">Подлежащее в именительном состоянии; дамма подразумевается, а танвин служит заменой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительное состояние</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَعْرِفُ مَعَانِيَ كَثِيرَةً لِهَذِهِ الْكَلِمَةِ.</span><span class="rule-table-ru">Я знаю много значений этого слова.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ بِالْفَتْحَةِ الظَّاهِرَةِ.</span><span class="rule-table-ru">Прямое дополнение в винительном состоянии с явно выраженной фатхой.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَرُّ</span><span class="rule-table-ru">родительное состояние</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَسْتَعْمِلُ هَذِهِ الْكَلِمَةَ بِمَعَانٍ كَثِيرَةٍ.</span><span class="rule-table-ru">Я употребляю это слово во многих значениях.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اِسْمٌ مَجْرُورٌ بِفَتْحَةٍ مُقَدَّرَةٍ، وَالتَّنْوِينُ لِلْعِوَضِ.</span><span class="rule-table-ru">Имя в родительном состоянии; фатха подразумевается, а танвин служит заменой.</span></td></tr></tbody></table></div></div></div>', 'Такое имя не принимает танвин и в родительном состоянии получает фатху вместо касры. При определённом артикле или идафе возвращается касра. Отдельно шарх разбирает неполные имена формы предельного множественного.', 'الْمَمْنُوعُ مِنَ الصَّرْفِ لَا يُنَوَّنُ، وَيُجَرُّ بِالْفَتْحَةِ نِيَابَةً عَنِ الْكَسْرَةِ، إِلَّا إِذَا اقْتَرَنَ بِأَلْ أَوْ أُضِيفَ فَيُجَرُّ بِالْكَسْرَةِ. وَالِاسْمُ الْمَنْقُوصُ الَّذِي عَلَى صِيغَةِ مُنْتَهَى الْجُمُوعِ، كَمَعَانٍ وَجَوَارٍ، يُعَامَلُ مُعَامَلَةَ الْمُفْرَدِ الْمَنْقُوصِ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '17'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '17'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ السَّابِعَ عَشَرَ
الْمَمْنُوعُ مِنَ الصَّرْفِ
الممنوعُ من الصَّرفِ ، هو : الاسْمُ الْمُعْرَبُ الَّذي لا يُنَوَّنُ .
أقسامُه: ينقسم إلى قسمين : ممنوع من الصَّرف لِعِلَّةٍ واحدةٍ ,وممنوع من الصَّرف لِعِلَّتَيْنِ .', 68, 68, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أ- الممنوعُ من الصَّرفِ لِعِلَّةٍ واحدةٍ
1- المختومُ بألفِ التَّأنيثِ المقصورةِ ، أو الممدودةِ ، بشرط أن تكون الألف زائدةً لا أصليةً ( ويُعرف ذلك بالرجوع إلى أصل الكلمة ) .
نحو : مَرْضَى , وجَرْحَى , ويَتَامَى ؛ وصَحْرَاء , وأَغْنِيَاء , وحَمْرَاء .
2- صِيغةُ مُنْتَهَى الْجُمُوعِ ( مَفَاعِلُ , ومَفَاعِيلُ ) وأَشْبَاهِهِمَا , نحو : مَسَاجِدَ , وفَنَادِقَ ؛ ومَصَابِيحَ , وثَعَابِينَ .
3- المفردُ الذي على وزنِ مُنتهى الجموعِ ، نحو : بَطَاطِسَ , وطَمَاطِمَ , وطَبَاشِيرَ , وسَرَاوِيلَ .', 68, 68, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ب- الممنوعُ من الصَّرفِ لِعِلَّتَيْنِ
وهو نوعان :
أ- العَلَمُ : تُمْنَعُ الأَعْلاَمُ الآتِيةُ من الصَّرفِ :
1- العلمُ المؤنَّثُ : نحو : فاطمةَ , وحمزةَ , ومريمَ .
إذا كانَ العلمُ المؤنَّثُ ثلاثياً ساكنَ الوسطِ جَازَ صرفُه ومنعُه , ومَنْعُهُ أَوْلَى .
نحو : هِنْدٍ , ورِيْمٍ , ودَعْدٍ .
2- العلمُ الأَعْجَمِيُّ : نحو : إبراهيمَ , وإسحاقَ , ولَنْدَنَ , وباكستانَ .
إذا كان العلمُ الأعجميُّ ثلاثيًّا ساكنَ الوسطِ مذكَّراً صُرِفَ , نحو: نُوْحٍ , ولُوْطٍ , وشَاْهٍ .
أما إذا كان مُؤَنَّثاً فيُمنع من الصَّرف , نحو : مُوْشَ ( مدينة في تركيا ) ونِيْسَ ( مدينة في فرنسا ) وبَلْخَ ( مدينة في أفغانستان ) .
3- العلمُ ووَزْنُ الْفِعْلِ ، نحو : أحْمَدَ , ويَزِيدَ , ويَنْبُعَ .
4- العلمُ الْمَعْدُولُ ، نحو : عُمَرَ ( قَدَّر النحويون أنه معدول من عَامِر ) وزُفَرَ (من زَافِر) وهُبَلَ (من هَابِل ) .
5- العلمُ المختومُ بِأَلِفٍ ونُونٍ زَائِدَتَيْنِ : نحو : عثمانَ , ورمضانَ , ومروانَ .
6- العلم الْمُرَكَّبُ تَرْكِيباً مَزْجِيّاً ، نحو : حَضْرَمَوْتَ , وبَعْلَبَكَّ , ومَعْدِيكَرِبَ .', 68, 69, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ب- الصِّفَةُ : تُمْنَعُ الصِّفاتُ الآتيةُ من الصَّرفِ :
1- الصِّفَةُ التي على وزنِ ( أَفْعَلَ ) نحو : أَكْبَرَ , وأَحْمَرَ , وأَحْسَنَ . يُشْتَرَطُ أَلاَّ يكون مؤنَّثه بالتَّاء ، فإذا كان مؤنَّثه بالتَّاء صُرِفَ , نحو : أَرْمَلٌ ( بالتنوين ) لأن مؤنَّثه بالتَّاء : أَرْمَلَةٌ .
2- الصِّفَةُ المختومةُ بألفٍ ونونٍ زائدتينِ ( على وزن فَعْلَانَ ) نحو : غَضْبَانَ , وفَرْحَانَ , وعَطْشَانَ .
3- الصَّفَةُ الْمَعْدُولَةُ : وهي شيئان :
أ- الْعَدَدُ الذي على وَزْنَيْ مَفْعَلٍ ، وفُعَالٍ , نحو : مَثْنَى وثُنَاءَ ، ومَثْلَثَ وثُلَاثَ ... إلخ ، وذلك إلى العدد (10 ) .
ب- كلمة أُخَرَ .', 69, 70, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أحكامُه :
أ- الممنوعُ من الصَّرْفِ لا يُنَوَّنُ .
ب- يُجَرُّ بالفتحةِ نيابةً عن الكسرةِ , نحو : صليت في مساجدَ كثيرةٍ .
إلا إذا اقترن بـ ( أل ) أو أُضِيفَ فَيُجَرُّ بالكسرة , نحو : صليتُ في المساجدِ .
صليتُ في مساجدِ المدينةِ .
ج- الاسمُ المنقوصُ الذي على صيغةِ مُنْتَهَى الْجُمُوعِ , نحو ( مَعَانٍ ، وجَوَارٍ ) يُعَامَلُ معاملةَ المفردِ من المنقوصِ ، ككلمة ( قَاضٍ ) .
تقول : لهذه الكلمةِ مَعَانٍ كثيرةٌ . مبتدأٌ مرفوعٌ بضمَّةٍ مُقَدَّرَةٍ ، والتَّنوينُ لِلْعِوَضِ .
أعرفُ مَعَانِيَ كثيرةً لهذه الكلمةِ . مفعولٌ به منصوبٌ بالفتحةِ الظَّاهرةِ .
أستعملُ هذه الكلمةَ بِمَعَانٍ كثيرةٍ ، اسمٌ مجرورٌ بفتحةٍ مُقَدَّرَةٍ ، والتَّنوينُ لِلْعِوَضِ .', 70, 70, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and sort_order = 5;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '17' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '17';
  if updated_count <> 5 or source_count <> 5 then
    raise exception 'Book 4 lesson 17 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
